import{_ as a,o as n,c as i,a2 as o}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"Weekly 002 — Digital Employee Control Plane and Work Runtime","description":"","frontmatter":{"title":"Weekly 002 — Digital Employee Control Plane and Work Runtime","outline":"deep"},"headers":[],"relativePath":"research/weekly/weekly-002.md","filePath":"research/weekly/weekly-002.md","lastUpdated":1785568227000}'),s={name:"research/weekly/weekly-002.md"};function t(l,e,r,c,p,d){return n(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="weekly-002-研究周报第-002-期" tabindex="-1">Weekly 002 / 研究周报第 002 期 <a class="header-anchor" href="#weekly-002-研究周报第-002-期" aria-label="Permalink to &quot;Weekly 002 / 研究周报第 002 期&quot;">​</a></h1><blockquote><p><strong>Digital Employee Control Plane and Work Runtime</strong><br><strong>数字员工控制面与工作 Runtime 的分层</strong><br> Published: 2026-08-01</p></blockquote><h2 id="executive-synthesis-核心综合" tabindex="-1">Executive synthesis / 核心综合 <a class="header-anchor" href="#executive-synthesis-核心综合" aria-label="Permalink to &quot;Executive synthesis / 核心综合&quot;">​</a></h2><p>The second issue moves from the basic definition of Digital Employee to a stronger engineering distinction:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee Control Plane</span></span>
<span class="line"><span>  identity, ownership, Position, authority, Registry,</span></span>
<span class="line"><span>  lifecycle, policy, cost, telemetry and evaluation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Digital Employee Work Runtime</span></span>
<span class="line"><span>  WorkOrder, planning, workflow, sessions, tools,</span></span>
<span class="line"><span>  checkpoint, recovery, evidence and completion</span></span></code></pre></div><p>第二期研究将数字员工平台拆分为两个互补层次：控制面负责身份、所有权、岗位、权限、名册、生命周期、政策、成本与评估；工作 Runtime 负责接单、规划、工作流、Session、工具、恢复、证据与完成。</p><p>This separation is important because enterprise platforms often provide strong workforce control without an open lightweight work runtime, while Agent frameworks provide execution primitives without organizational control.</p><h2 id="workday-control-plane-benchmark-workday-控制面对标" tabindex="-1">Workday: control-plane benchmark / Workday：控制面对标 <a class="header-anchor" href="#workday-control-plane-benchmark-workday-控制面对标" aria-label="Permalink to &quot;Workday: control-plane benchmark / Workday：控制面对标&quot;">​</a></h2><p>Workday Agent System of Record is the strongest current signal for workforce management. It treats Agents as governed enterprise resources and records:</p><ul><li>organizational owner;</li><li>role and skills;</li><li>usage and observability;</li><li>security and data access;</li><li>cost and ROI;</li><li>compliance and conformance;</li><li>lifecycle and improvement.</li></ul><p>The lesson is not to copy Workday&#39;s enterprise stack. It is to make persistent identity, ownership, policy and economics first-class objects.</p><h2 id="openhands-operator-workspace-benchmark-openhands-操作工作空间对标" tabindex="-1">OpenHands: operator workspace benchmark / OpenHands：操作工作空间对标 <a class="header-anchor" href="#openhands-operator-workspace-benchmark-openhands-操作工作空间对标" aria-label="Permalink to &quot;OpenHands: operator workspace benchmark / OpenHands：操作工作空间对标&quot;">​</a></h2><p>OpenHands Agent Canvas provides a useful engineering benchmark for:</p><ul><li>self-hosted Agent operation;</li><li>skill and plugin visibility;</li><li>connection health;</li><li>manual, scheduled and event-triggered automation;</li><li>desktop and operator console experience.</li></ul><p>Its primary abstraction remains an Agent workspace. CodeFlowMu should learn the operational mechanisms while maintaining a Position-centric product model.</p><h2 id="architectural-judgment-架构判断" tabindex="-1">Architectural judgment / 架构判断 <a class="header-anchor" href="#architectural-judgment-架构判断" aria-label="Permalink to &quot;Architectural judgment / 架构判断&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Organization</span></span>
<span class="line"><span>    ↓ defines</span></span>
<span class="line"><span>Position</span></span>
<span class="line"><span>    ↓ registered in</span></span>
<span class="line"><span>Digital Employee Control Plane</span></span>
<span class="line"><span>    ↓ issues</span></span>
<span class="line"><span>WorkOrder</span></span>
<span class="line"><span>    ↓ executed by</span></span>
<span class="line"><span>CodeFlowMu Work Runtime</span></span>
<span class="line"><span>    ↓ uses</span></span>
<span class="line"><span>Agent Providers + Tools + Rules + Humans</span></span>
<span class="line"><span>    ↓ produces</span></span>
<span class="line"><span>TMPA / FCoP governed Outcome</span></span></code></pre></div><p>The Control Plane should not become a second execution engine. The Runtime should not silently own organizational policy. They exchange stable contracts.</p><h2 id="codeflowmu-target-codeflowmu-目标结构" tabindex="-1">CodeFlowMu target / CodeFlowMu 目标结构 <a class="header-anchor" href="#codeflowmu-target-codeflowmu-目标结构" aria-label="Permalink to &quot;CodeFlowMu target / CodeFlowMu 目标结构&quot;">​</a></h2><h3 id="control-plane" tabindex="-1">Control plane <a class="header-anchor" href="#control-plane" aria-label="Permalink to &quot;Control plane&quot;">​</a></h3><ul><li>PositionRegistry;</li><li>DigitalEmployeeRegistry;</li><li>owner and organizational placement;</li><li>TeamPolicy and authority;</li><li>credentials and access references;</li><li>lifecycle and version;</li><li>provider bindings;</li><li>cost, SLA and evaluation records;</li><li>compliance and audit views.</li></ul><h3 id="work-runtime" tabindex="-1">Work runtime <a class="header-anchor" href="#work-runtime" aria-label="Permalink to &quot;Work runtime&quot;">​</a></h3><ul><li>current PM as Work Manager;</li><li>WorkOrder and Plan;</li><li>WorkflowCatalog and OperationNodeCatalog;</li><li>SessionManager and TaskDispatcher;</li><li>Browser/Windows/Source/API tool ports;</li><li>Checkpoint, retry and recovery;</li><li>Event Outbox and TMPA Adapter;</li><li>FCoP coordination;</li><li>Business and Publication Completion Gates.</li></ul><h2 id="sme-first-constraint-sme-first-约束" tabindex="-1">SME-first constraint / SME-first 约束 <a class="header-anchor" href="#sme-first-constraint-sme-first-约束" aria-label="Permalink to &quot;SME-first constraint / SME-first 约束&quot;">​</a></h2><p>Enterprise systems prove that governance is necessary, but their infrastructure is too heavy for many small organizations. CodeFlowMu should implement a coherent minimum:</p><ul><li>file-native or small-service deployment;</li><li>a small number of persistent concepts;</li><li>provider independence;</li><li>explicit cost budgets;</li><li>human authority without a large control-tower team;</li><li>exportable evidence and indexes.</li></ul><h2 id="recommended-engineering-tasks-建议工程任务" tabindex="-1">Recommended engineering tasks / 建议工程任务 <a class="header-anchor" href="#recommended-engineering-tasks-建议工程任务" aria-label="Permalink to &quot;Recommended engineering tasks / 建议工程任务&quot;">​</a></h2><ol><li>Define a minimal Position Registry view using existing Agent and Edition data.</li><li>Add ownership, status, version, provider, allowed tools and cost-policy fields as an experimental projection.</li><li>Keep existing PM/FCoP/Runtime behavior unchanged while the control-plane projection is validated.</li><li>Expose health, active work, HOLD, recovery and provider failure in one runtime console.</li><li>Use Open Dev Team as the first registered Digital Employee.</li><li>Validate the model with the Saige short-rental employee before building a full Studio.</li></ol><h2 id="research-conclusion-研究结论" tabindex="-1">Research conclusion / 研究结论 <a class="header-anchor" href="#research-conclusion-研究结论" aria-label="Permalink to &quot;Research conclusion / 研究结论&quot;">​</a></h2><p>The competitive space is no longer simply “which framework has more Agents.” The emerging system category is:</p><blockquote><p><strong>A governed workforce control plane connected to a reliable AI work runtime.</strong></p></blockquote><p>CodeFlowMu&#39;s opportunity is to provide the lightweight, engineering-driven SME version of that category.</p>`,32)])])}const m=a(s,[["render",t]]);export{u as __pageData,m as default};
